function element(tag, className, text) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

async function loadJson(path) {
  const response = await fetch(path, { cache: "no-store" });
  if (!response.ok) throw new Error(`Failed to load ${path}`);
  return response.json();
}

// Release URLs are generated by the publisher, always within this site's channels.
function releaseUrl(value, channel, filename) {
  const pattern = new RegExp(`^channels/${channel}/[a-f0-9]{64}/${filename.replaceAll(".", "\\.")}$`);
  if (typeof value !== "string" || !pattern.test(value)) throw new Error("Invalid release URL");
  return value;
}

function releaseCard(channel, release) {
  if (typeof release.version !== "string" || typeof release.notes !== "string") {
    throw new Error("Invalid release metadata");
  }
  const manifest = releaseUrl(release.manifest, channel, "manifest.json");
  const ota = releaseUrl(release.ota, channel, "firmware_ota.bin");
  const beta = channel === "beta";
  const label = beta ? "ベータ版" : "正式版";
  const card = element("section", "card");
  const heading = element("h2", beta ? "beta-label" : "", `最新の${label}`);
  heading.id = `${channel}-title`;
  card.setAttribute("aria-labelledby", heading.id);
  card.append(heading);
  card.append(element("div", "meta", `v${release.version}${release.date ? ` ／ ${release.date.slice(0, 10)}` : ""}`));
  if (beta) card.append(element("p", "beta-label", "動作確認用のベータ版です。説明と確認事項を読んでからご利用ください。"));
  card.append(element("p", "release-notes", release.notes));
  const actions = element("div", "actions");
  const installer = element("esp-web-install-button");
  installer.setAttribute("manifest", manifest);
  const button = element("button", "connect-btn", `${label}をUSBで書き込む`);
  button.slot = "activate";
  installer.append(button);
  const download = element("a", "download-btn", `${label}をSD用にダウンロード`);
  download.href = ota;
  download.download = "firmware_ota.bin";
  actions.append(installer, download);
  card.append(actions);
  return card;
}

async function loadReleases() {
  const status = document.getElementById("release-status");
  const list = document.getElementById("release-list");
  try {
    const releases = await loadJson("releases.json");
    if (releases.schema_version !== 1 || !releases.stable) throw new Error("Missing stable release");
    // Assemble both cards before making download/write controls available.
    const cards = [releaseCard("stable", releases.stable)];
    if (releases.beta) cards.push(releaseCard("beta", releases.beta));
    list.replaceChildren(...cards);
    status.hidden = true;
  } catch (_) {
    list.replaceChildren();
    status.textContent = "配布情報を取得できませんでした。ページを再読み込みしてください。";
  }
}

async function loadHistory() {
  const list = document.getElementById("history-list");
  try {
    const entries = await loadJson("changelog.json");
    if (!Array.isArray(entries)) throw new Error("Invalid history");
    const rows = entries.map((entry) => {
      const row = element("li");
      if (entry.date) row.append(element("span", "date", entry.date));
      if (entry.version) row.append(element("span", "ver", `v${entry.version}`));
      row.append(element("span", "history-text", entry.text || "更新内容"));
      return row;
    });
    list.replaceChildren(...(rows.length ? rows : [element("li", "", "履歴はまだありません。") ]));
  } catch (_) {
    list.replaceChildren(element("li", "", "履歴の読み込みに失敗しました。"));
  }
}

loadReleases();
loadHistory();
